<script setup>
import {ref,onBeforeUnmount} from 'vue';
import {compareNativeZip} from '../shared/native-measurement-compare.mjs';
import {MAX_ADAPTER_ZIP_BYTES} from '../shared/stored-zip.mjs';
const props=defineProps({sceneData:{type:Object,required:true},manifest:{type:Object,required:true},archiveIdentity:{type:Object,required:true}}),result=ref(null),busy=ref(false),message=ref('');let disposed=false;onBeforeUnmount(()=>{disposed=true;});
const number=v=>v===null?'—':new Intl.NumberFormat('en',{maximumFractionDigits:6,signDisplay:'exceptZero'}).format(v);
async function choose(event){const file=event.target.files?.[0];event.target.value='';if(!file||busy.value)return;result.value=null;message.value='';busy.value=true;try{if(file.size>MAX_ADAPTER_ZIP_BYTES)throw Error('Comparison ZIP exceeds archive size limit');const next=await compareNativeZip({scene:props.sceneData,manifest:props.manifest,identity:props.archiveIdentity},new Uint8Array(await file.arrayBuffer()));if(disposed)return;result.value=next;message.value='Compared verified ZIPs: '+next.summary.added+' added, '+next.summary.removed+' removed, '+next.summary.changed+' changed measurements, '+next.summary.unchanged+' unchanged measurements.';}catch(error){if(!disposed)message.value=error.message;}finally{if(!disposed)busy.value=false;}}
function download(){if(!result.value)return;const url=URL.createObjectURL(new Blob([JSON.stringify(result.value,null,2)+'\n'],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='terratec-native-measurement-comparison.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
</script>
<template><section aria-label="Native measurement comparison"><label>Compare another verified native ZIP<input :disabled="busy" type="file" accept=".zip,application/zip" @change="choose"></label><p>Candidate minus the current bundle · matching scoped IDs · default native resource limits. Receiver placement affects coordinates; no automatic alignment is performed.</p><p data-testid="native-comparison-status" role="status">{{ message }}</p><div v-if="result" data-testid="native-comparison-result"><p>Current ZIP: {{ result.before.archive.archiveSha256 }}<br>Candidate ZIP: {{ result.after.archive.archiveSha256 }}</p><button @click="download">Export native comparison JSON</button><div class="native-comparison-table"><table aria-label="Native measurement changes"><thead><tr><th>Source element</th><th>Status</th><th>Area Δ (m²)</th><th>Span Δ X/Y/Z (m)</th><th>Centre Δ X/Y/Z (m)</th></tr></thead><tbody><tr v-for="row in result.elements" :key="row.elementId"><th>{{ row.elementId }}</th><td>{{ row.status }}</td><td>{{ number(row.delta?.triangulatedArea??null) }}</td><td>{{ row.delta?['x','y','z'].map(a=>number(row.delta.axisAlignedSpans[a])).join(' / '):'—' }}</td><td>{{ row.delta?['x','y','z'].map(a=>number(row.delta.centre[a])).join(' / '):'—' }}</td></tr></tbody></table></div><p>Added/removed elements have no inferred delta. Unchanged measurements do not prove identical geometry. The JSON retains material changes, source ranges, approximation labels and comparison limitations.</p></div></section></template>
<style>.native-comparison-table{max-height:24vh;overflow:auto}.native-comparison-table table{border-collapse:collapse;font-size:12px}.native-comparison-table th,.native-comparison-table td{padding:3px 6px;border:1px solid #a3b6ad;text-align:left;overflow-wrap:anywhere}</style>
